 const FVector SUp=FVector::UpVector;const FVector SRight=(SB[Source(TEXT("thigh_r"))].GetLocation()-SB[Source(TEXT("thigh_l"))].GetLocation()).GetSafeNormal();FVector SFront=FVector::CrossProduct(SRight,SUp).GetSafeNormal();FTransform RootA,RootB;Walk->GetBoneTransform(RootA,FSkeletonPoseBoneIndex(0),FAnimExtractContext(0.,false),false);Walk->GetBoneTransform(RootB,FSkeletonPoseBoneIndex(0),FAnimExtractContext(Walk->GetPlayLength()-.00001,false),false);if(FVector::DotProduct(SFront,RootB.GetLocation()-RootA.GetLocation())<0)SFront=-SFront;
 FVector Feet=FVector::ZeroVector;for(const auto& S:Body->LegRest)if(!S.bCalf)Feet+=Neutral[S.Foot].GetLocation()*.5;
