 auto ClipSpeed=[&](UAnimSequence* Clip){FTransform A,B;Clip->GetBoneTransform(A,FSkeletonPoseBoneIndex(0),FAnimExtractContext(0.,false),false);Clip->GetBoneTransform(B,FSkeletonPoseBoneIndex(0),FAnimExtractContext(Clip->GetPlayLength()-.00001,false),false);return FVector::VectorPlaneProject(B.GetLocation()-A.GetLocation(),SUp).Size()/Clip->GetPlayLength();};const double WalkSpeed=ClipSpeed(Walk),RunSpeed=ClipSpeed(Run);if(!Test.TestTrue(TEXT("Measured source root speeds available"),WalkSpeed>10&&RunSpeed>WalkSpeed))return false;auto IdlePose=SB;const auto RawIdle=Sample(Idle,0);for(const TCHAR* Part:{TEXT("upperarm"),TEXT("lowerarm"),TEXT("hand")}){const int L=Source(*(FString(Part)+TEXT("_l"))),R=Source(*(FString(Part)+TEXT("_r")));const FVector LP=RawIdle[L].GetLocation(),RP=RawIdle[R].GetLocation();const FVector Mid=(LP+RP)*.5;const double Width=FMath::Abs(FVector::DotProduct(RP-LP,SRight))*.5;const FVector Center=Mid-SRight*FVector::DotProduct(Mid-SB[SP].GetLocation(),SRight);IdlePose[L].SetLocation(Center-SRight*Width);IdlePose[R].SetLocation(Center+SRight*Width);}
