 TArray<AActor*> Props;auto Box=[&](const FVector& Location,const FVector& Size){auto* A=World->SpawnActor<AActor>();auto* M=NewObject<UStaticMeshComponent>(A);A->SetRootComponent(M);M->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Cube.Cube")));M->SetCollisionEnabled(ECollisionEnabled::NoCollision);if(Props.IsEmpty())M->SetMaterial(0,GroundMaterial);M->RegisterComponent();A->SetActorLocation(Location);A->SetActorScale3D(Size/100);Props.Add(A);};
 const FVector WF=Initial.TransformVectorNoScale(Front),WR=Initial.TransformVectorNoScale(Right),WU=Initial.TransformVectorNoScale(Up);const FVector Ground=Initial.TransformPosition(Feet-Up*8);
 Box(Ground+WF*2000-WU*5,FVector(6000,6000,10));for(int I=-2;I<45;++I){Box(Ground+WF*(I*100)+WR*110+WU*1,FVector(8,8,2));Box(Ground+WF*(I*100)-WR*110+WU*1,FVector(8,8,2));}
 for(TActorIterator<APawn> It(World);It;++It)Capture->HideActorComponents(*It);TArray<UPointLightComponent*> Points;Actor->GetComponents(Points);for(auto* P:Points)P->SetIntensity(0);TArray<UDirectionalLightComponent*> ExistingSuns;Actor->GetComponents(ExistingSuns);for(auto* L:ExistingSuns)L->SetIntensity(0);auto* Fill=NewObject<UDirectionalLightComponent>(Actor);Fill->Intensity=.7;Fill->RegisterComponent();Fill->SetWorldRotation((-WF+WR-WU*.3).Rotation());auto* Sun=NewObject<UDirectionalLightComponent>(Actor);Sun->Intensity=3;Sun->RegisterComponent();Sun->SetWorldRotation((WF-WR-WU).Rotation());
 Capture->TextureTarget->ResizeTarget(1280,720);Capture->FOVAngle=60;Capture->PostProcessSettings.AutoExposureBias=1;Capture->ShowFlags.SetMotionBlur(false);Capture->ShowFlags.SetTemporalAA(false);
 const bool HairView=FParse::Param(FCommandLine::Get(),TEXT("VamHairView"));
 auto* BackdropMaterial=NewObject<UMaterial>(GetTransientPackage());BackdropMaterial->SetShadingModel(MSM_Unlit);auto* BackdropColor=NewObject<UMaterialExpressionConstant3Vector>(BackdropMaterial);BackdropColor->Constant=FLinearColor(.22,.25,.3);BackdropMaterial->GetExpressionCollection().AddExpression(BackdropColor);BackdropMaterial->GetEditorOnlyData()->EmissiveColor.Expression=BackdropColor;BackdropMaterial->PostEditChange();BackdropMaterial->ForceRecompileForRendering();if(GShaderCompilingManager)GShaderCompilingManager->FinishAllCompilation();Box(Start,FVector(3000,5,3000));auto* Backdrop=Props.Last();CastChecked<UStaticMeshComponent>(Backdrop->GetRootComponent())->SetMaterial(0,BackdropMaterial);
 auto Camera=[&](){const FTransform F=Actor->GetActorTransform();const FVector CF=F.TransformVectorNoScale(Front),CR=F.TransformVectorNoScale(Right);const FVector Look=F.TransformPosition(HairView?Body->GetComponentSpaceTransforms()[Head].GetLocation()+Up*5:Neutral[Pelvis].GetLocation()-Up*18);const FVector Eye=Look-CF*(HairView?100:340)+CR*(HairView?30:75)+WU*(HairView?6:65);Backdrop->SetActorLocation(F.GetLocation()+CF*600+WU*300);Backdrop->SetActorRotation(FRotationMatrix::MakeFromYZ(CF,WU).Rotator());Sun->SetWorldRotation((CF-CR-WU).Rotation());Fill->SetWorldRotation((-CF+CR-WU*.3).Rotation());Capture->SetWorldLocationAndRotation(Eye,FRotationMatrix::MakeFromXZ((Look+CF*(HairView?0:35)+CR*(HairView?0:45)-Eye).GetSafeNormal(),WU).Rotator());};
